BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('HBSE-108-1-006','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-01-19。本題考兒童及少年福利與權益保障法第64條（列為保護個案者應於三個月內提出家庭處遇計畫，處遇計畫得包括家庭功能評估、安全與安置評估、親職教育等）；2019-04-24 修正僅調整引用款次並增訂行方不明之處理，三個月期限及處遇計畫內容未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP104-1-22','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年福利與權益保障法第15條、第16條、第17條（收出養媒合與出養程序），最後修正公布日：第15條 2015-02-04、第16條 2011-11-30、第17條 2011-11-30，本題考試日 2015-02-07 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP104-1-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考兒童及少年福利與權益保障法第64條（列為保護個案者應於三個月內提出家庭處遇計畫，處遇計畫得包括家庭功能評估、安全與安置評估、親職教育等）；2019-04-24 修正僅調整引用款次並增訂行方不明之處理，三個月期限及處遇計畫內容未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP104-2-05','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考社會立法之法律名稱沿革（性侵害犯罪防治法自制定以來名稱未曾變更），非兒童及少年福利與權益保障法條文內容，不受日後條文修正影響，官方答案仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP104-2-22','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年福利與權益保障法第15條、第17條（收出養媒合服務），最後修正公布日：第15條 2015-02-04、第17條 2011-11-30，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP104-2-23','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考兒童及少年福利與權益保障法第25條、第26條。考試時規定「應年滿二十歲」，選項(C)「年滿18歲」因此錯誤（官方答案A）；2021-01-20 修正為「應為成年」（2023-01-01 起十八歲為成年），選項(C)年齡部分已與現行條文相符。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP104-2-28','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-07-25。本題考兒童及少年福利與權益保障法第26條之1（不得擔任居家式托育服務提供者之情事）；2019-01-02 修正將第1款罪名改列為性侵害犯罪防治法第2條第1項之罪等、第5款改為有客觀事實認有傷害兒童之虞，毒品罪、虐待等款未變，「家族成員曾罹患精神疾病」仍非法定事由。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP104-2-29','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年福利與權益保障法第57條（緊急安置七十二小時與繼續安置三個月），最後修正公布日：第57條 2011-11-30，本題考試日 2015-07-25 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP105-1-27','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年福利與權益保障法第102條（親職教育輔導四小時以上五十小時以下），最後修正公布日：第102條 2015-02-04，本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP105-1-31','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考兒童及少年福利與權益保障法第25條、第26條、第26條之2；共同居住之人有毒品罪等情事者，居家式托育服務提供者以提供到宅托育為限，2019-01-02 修正僅改第26條之2第2款，選項(B)仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP105-1-32','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考兒童及少年福利與權益保障法第64條（列為保護個案者應於三個月內提出家庭處遇計畫，處遇計畫得包括家庭功能評估、安全與安置評估、親職教育等）；2019-04-24 修正僅調整引用款次並增訂行方不明之處理，三個月期限及處遇計畫內容未變。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP105-1-33','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考兒童及少年福利與權益保障法第15條、第16條（收出養媒合與國內收養優先），最後修正公布日：第15條 2015-02-04、第16條 2011-11-30，本題考試日 2016-01-30 之後未再修正，考試時條文與現行條文相同，官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP105-1-35','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考兒童及少年福利與權益保障法第54條（兒少家庭風險之責任通報及預防性服務）；2019-04-24 修正增列六歲以下兒童未辦理出生登記等通報事由及資料提供規定，服務對象仍為兒童及少年（未滿十八歲），選項(D)「十二歲以下」仍錯誤。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050001'),('SP105-2-19','verified_current'